<script setup lang="ts">
import { nextTick, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ArrowRight, ChevronDown, FilePenLine, Globe2, Image, Link, LockKeyhole, PanelTop, ShieldCheck, Store, Tags, Type, Upload, Users, X } from 'lucide-vue-next';
import { api, getFriendlyError } from '@/lib/api';
import { useAuthStore } from '@/stores/auth';

const router = useRouter(); const route = useRoute(); const authStore = useAuthStore();
const navItems = [{ label: '首页', path: '/home-public' }, { label: '产品能力', path: '/product-capabilities' }, { label: '适用平台', path: '/platforms' }, { label: '解决方案', path: '/solutions' }, { label: '关于智选优发', path: '/about-project' }];
const mainNavItems = navItems.slice(0, 3); const moreNavItems = navItems.slice(3);
const moreOpen = ref(false); const contactOpen = ref(false); const emailCopied = ref(false); const authModalOpen = ref(false); const authMode = ref<'login' | 'register'>('login'); const authLoading = ref(false); const authError = ref('');
const loginForm = reactive({ email: '', password: '', role: '' }); const registerForm = reactive({ companyName: '', contactName: '', email: '' });
function scrollTo(id: string) { document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
function goTo(path: string) { router.push(path); }
async function copyContactEmail() { try { await navigator.clipboard.writeText('wangbo030127@gmail.com'); } finally { emailCopied.value = true; } }
function openAuth(mode: 'login' | 'register') { router.push({ path: '/home-public', query: { ...route.query, auth: mode } }); }
function closeAuth() { const query = { ...route.query } as Record<string, string>; delete query.auth; router.replace({ path: '/home-public', query }); }
watch(() => route.query.auth, () => { const mode = String(route.query.auth || ''); authModalOpen.value = mode === 'login' || mode === 'register'; if (authModalOpen.value) { authMode.value = mode as 'login' | 'register'; authError.value = ''; } }, { immediate: true });
async function ensureLoginRoleField() {
  if (!authModalOpen.value || authMode.value !== 'login') return;
  await nextTick();
  const form = document.querySelector<HTMLFormElement>('.auth-modal form');
  if (!form || form.querySelector('[data-login-role]')) return;
  const label = document.createElement('label');
  label.dataset.loginRole = 'true';
  label.append('登录角色');
  const select = document.createElement('select');
  select.required = true;
  const options = [['', '请选择角色'], ['ENTERPRISE_ADMIN', '企业管理员'], ['OPERATOR', '运营人员'], ['DESIGNER', '设计人员'], ['REVIEWER', '复核人员'], ['MANAGER', '管理人员'], ['SYSTEM_ADMIN', '系统管理员'], ['CUSTOMER_VIEWER', '客户查看员']];
  for (const [value, text] of options) { const option = new Option(text, value); option.disabled = !value; select.add(option); }
  select.value = loginForm.role;
  select.addEventListener('change', () => { loginForm.role = select.value; });
  label.append(select);
  form.insertBefore(label, form.querySelector('.form-error') || form.querySelector('.primary-btn'));
}
watch([authModalOpen, authMode], () => { void ensureLoginRoleField(); }, { immediate: true });
async function submitLogin() { authLoading.value = true; authError.value = ''; try { await api.login(loginForm); authStore.syncFromStorage(); router.push('/home'); } catch (error) { authError.value = getFriendlyError(error); } finally { authLoading.value = false; } }
async function submitRegister() { authLoading.value = true; authError.value = ''; try { const result: any = await api.applyCommercial({ type: 'ACCOUNT_OPENING', companyName: registerForm.companyName, contactName: registerForm.contactName, email: registerForm.email }); authMode.value = 'login'; loginForm.email = registerForm.email; authError.value = result?.message || '申请已提交，请使用获批账号登录。'; } catch (error) { authError.value = getFriendlyError(error); } finally { authLoading.value = false; } }
</script>

